CREATE TABLE IF NOT EXISTS admin_audit_log (action TEXT, admin_id TEXT, created_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), details TEXT DEFAULT '{}', id TEXT PRIMARY KEY, target_id TEXT, target_type TEXT);
