CREATE TABLE IF NOT EXISTS ai_usage_logs (capability TEXT, created_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), function_name TEXT, id TEXT PRIMARY KEY, metadata TEXT DEFAULT '{}', provider TEXT, source TEXT DEFAULT 'manual', status TEXT DEFAULT 'active', tokens REAL DEFAULT 0, user_id TEXT);
CREATE INDEX IF NOT EXISTS idx_ai_usage_logs_user_id ON ai_usage_logs(user_id);
CREATE TABLE IF NOT EXISTS announcements (active INTEGER DEFAULT 1, body TEXT, created_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), created_by TEXT, ends_at TEXT, id TEXT PRIMARY KEY, level TEXT DEFAULT 'info', starts_at TEXT, title TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS background_tasks (created_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), error TEXT, id TEXT PRIMARY KEY, input TEXT DEFAULT '{}', progress REAL DEFAULT 0, result TEXT DEFAULT '{}', session_id TEXT, status TEXT DEFAULT 'active', task_type TEXT DEFAULT 'chat', updated_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), user_id TEXT);
