CREATE INDEX IF NOT EXISTS idx_background_tasks_user_id ON background_tasks(user_id);
CREATE TABLE IF NOT EXISTS chat_messages (content TEXT, created_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), id TEXT PRIMARY KEY, image_url TEXT, metadata TEXT DEFAULT '{}', role TEXT DEFAULT 'user', session_id TEXT);
CREATE INDEX IF NOT EXISTS idx_chat_messages_session_id ON chat_messages(session_id);
CREATE TABLE IF NOT EXISTS chat_sessions (created_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), id TEXT PRIMARY KEY, mode TEXT DEFAULT 'chat', preview TEXT DEFAULT '', story_state TEXT DEFAULT '{}', title TEXT DEFAULT '', tool_id TEXT, project_id TEXT, pinned INTEGER DEFAULT 0, updated_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), user_id TEXT);
CREATE INDEX IF NOT EXISTS idx_chat_sessions_user_id ON chat_sessions(user_id);
