CREATE TABLE IF NOT EXISTS leads (avg_views REAL DEFAULT 0, campaign_id TEXT, channel_url TEXT, created_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), display_name TEXT DEFAULT '', email TEXT, email_status TEXT DEFAULT 'unknown', id TEXT PRIMARY KEY, industry TEXT, metadata TEXT DEFAULT '{}', niche TEXT, primary_domain TEXT, prospecting_job_id TEXT, source TEXT DEFAULT 'manual', source_id TEXT, status TEXT DEFAULT 'active', subscriber_count REAL DEFAULT 0, updated_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), user_id TEXT, workflow_id TEXT);
CREATE INDEX IF NOT EXISTS idx_leads_user_id ON leads(user_id);
CREATE TABLE IF NOT EXISTS outreach_campaigns (created_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), daily_cap REAL DEFAULT 0, follow_up_enabled INTEGER DEFAULT 1, id TEXT PRIMARY KEY, name TEXT, pitch_context TEXT DEFAULT '', status TEXT DEFAULT 'active', throttle_max_sec REAL DEFAULT 0, throttle_min_sec REAL DEFAULT 0, tone TEXT DEFAULT 'friendly', updated_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), user_id TEXT);
CREATE INDEX IF NOT EXISTS idx_outreach_campaigns_user_id ON outreach_campaigns(user_id);
CREATE TABLE IF NOT EXISTS plan_limits (active INTEGER DEFAULT 1, created_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), display_name TEXT DEFAULT '', features TEXT DEFAULT '{}', limits TEXT DEFAULT '{}', plan TEXT PRIMARY KEY, popular INTEGER DEFAULT 0, price_monthly REAL DEFAULT 0, price_yearly REAL DEFAULT 0, sort_order REAL DEFAULT 0, tagline TEXT, updated_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS profiles (avatar_url TEXT, created_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), email TEXT, full_name TEXT, id TEXT PRIMARY KEY, is_banned INTEGER DEFAULT 0, updated_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS prospecting_jobs (created_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), error TEXT, found_count REAL DEFAULT 0, id TEXT PRIMARY KEY, params TEXT DEFAULT '{}', source TEXT DEFAULT 'manual', status TEXT DEFAULT 'active', target_count REAL DEFAULT 0, updated_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), user_id TEXT);
CREATE INDEX IF NOT EXISTS idx_prospecting_jobs_user_id ON prospecting_jobs(user_id);
CREATE TABLE IF NOT EXISTS story_projects (analysis TEXT DEFAULT '{}', audience TEXT, audio_url TEXT, category TEXT, characters TEXT DEFAULT '[]', created_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), error TEXT, generation_mode TEXT, id TEXT PRIMARY KEY, language TEXT DEFAULT 'en', length TEXT, progress TEXT DEFAULT '{}', prompts TEXT DEFAULT '[]', scenes TEXT DEFAULT '[]', script TEXT, session_id TEXT, status TEXT DEFAULT 'active', title TEXT DEFAULT '', topic TEXT, updated_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), user_id TEXT);
